//! The port against the JS modules: `testdata/vectors.json` is generated by
//! `src/lib/pixelmap/coreVectors.test.ts` from the code the editor path runs.

use std::net::{Ipv4Addr, UdpSocket};
use std::time::{Duration, Instant};

use base64::Engine;
use serde_json::Value;

use super::colour::{self, Frame, PixelOptions, SamplingMode, TestPattern};
use super::output::{OutFrame, Output, Protocol, SacnSettings, UniverseFrame};
use super::packets::{self, E131Options};
use super::plan;

fn vectors() -> Value {
    serde_json::from_str(include_str!("testdata/vectors.json")).expect("vectors.json parses")
}

fn unhex(text: &str) -> Vec<u8> {
    (0..text.len()).step_by(2).map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap()).collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

fn str_of<'a>(value: &'a Value, key: &str) -> &'a str {
    value[key].as_str().unwrap_or_else(|| panic!("{key} missing"))
}

fn options_of(value: &Value) -> PixelOptions {
    let calibration = &value["calibration"];
    PixelOptions {
        brightness: value["brightness"].as_f64(),
        gamma: value["gamma"].as_f64(),
        red_gain: calibration["redGain"].as_f64(),
        green_gain: calibration["greenGain"].as_f64(),
        blue_gain: calibration["blueGain"].as_f64(),
        saturation: calibration["saturation"].as_f64(),
        black_threshold: calibration["blackThreshold"].as_f64(),
        smoothing: calibration["smoothing"].as_f64(),
        color_matrix: calibration["colorMatrix"].as_array().map(|m| m.iter().map(|v| v.as_f64().unwrap()).collect()),
    }
}

#[test]
fn packets_match_the_js_builders() {
    let vectors = vectors();
    let cid = packets::parse_sacn_cid(str_of(&vectors, "cid")).unwrap();
    let mut checked = 0;
    for case in vectors["packets"].as_array().unwrap() {
        let data = case.get("data").and_then(Value::as_str).map(unhex).unwrap_or_default();
        let built = match str_of(case, "kind") {
            "artdmx" => packets::build_art_dmx(case["universe"].as_u64().unwrap() as u32, case["sequence"].as_u64().unwrap() as u8, 0, &data).unwrap(),
            "artsync" => packets::build_art_sync(),
            "e131" => {
                let name = packets::encode_source_name(case["sourceName"].as_str());
                packets::build_e131(&E131Options {
                    universe: case["universe"].as_u64().unwrap() as u32,
                    sequence: case["sequence"].as_u64().unwrap() as u8,
                    priority: case["priority"].as_u64().unwrap() as u8,
                    source_name: &name,
                    cid: &cid,
                    preview: case["preview"].as_bool().unwrap_or(false),
                    terminated: case["terminated"].as_bool().unwrap_or(false),
                    force_sync: case["forceSync"].as_bool().unwrap_or(false),
                    sync_address: case["syncAddress"].as_u64().unwrap_or(0) as u16,
                }, &data).unwrap()
            }
            "wled" => packets::build_wled_realtime(&data).unwrap(),
            other => panic!("unknown packet kind {other}"),
        };
        assert_eq!(hex(&built), str_of(case, "packet"), "{case}");
        checked += 1;
    }
    assert!(checked >= 15);
}

#[test]
fn packet_validation_matches_the_js_limits() {
    assert!(packets::build_art_dmx(32768, 1, 0, &[0, 0]).is_err());
    assert!(packets::build_art_dmx(0, 1, 0, &[]).is_err());
    assert!(packets::build_art_dmx(0, 1, 0, &[0; 513]).is_err());
    let name = packets::encode_source_name(None);
    let cid = [0; 16];
    let options = |universe| E131Options { universe, sequence: 0, priority: 100, source_name: &name, cid: &cid, preview: false, terminated: false, force_sync: false, sync_address: 0 };
    assert!(packets::build_e131(&options(0), &[0]).is_err());
    assert!(packets::build_e131(&options(64000), &[0]).is_err());
    assert!(packets::build_wled_realtime(&[1, 2]).is_err());
    assert!(packets::build_wled_realtime(&[0; 491 * 3]).is_err());
    assert!(packets::parse_sacn_cid("not-a-uuid").is_err());
    assert_eq!(packets::next_artnet_sequence(None), 1);
    assert_eq!(packets::next_artnet_sequence(Some(255)), 1);
    assert_eq!(packets::next_artnet_sequence(Some(7)), 8);
    assert_eq!(packets::next_sacn_sequence(None), 0);
    assert_eq!(packets::next_sacn_sequence(Some(255)), 0);
    assert_eq!(packets::sacn_multicast_address(0x1234).unwrap(), Ipv4Addr::new(239, 255, 0x12, 0x34));
}

fn picture(vectors: &Value) -> (Vec<u8>, usize, usize) {
    let p = &vectors["picture"];
    let rgba = base64::engine::general_purpose::STANDARD.decode(str_of(p, "rgba")).unwrap();
    (rgba, p["width"].as_u64().unwrap() as usize, p["height"].as_u64().unwrap() as usize)
}

fn to_bgra(rgba: &[u8]) -> Vec<u8> {
    rgba.chunks_exact(4).flat_map(|p| [p[2], p[1], p[0], p[3]]).collect()
}

#[test]
fn sampling_matches_the_js_sampler_in_every_mode() {
    let vectors = vectors();
    let (rgba, width, height) = picture(&vectors);
    let bgra = to_bgra(&rgba);
    let flat: Vec<f64> = vectors["sampling"]["points"].as_array().unwrap().iter().map(|v| v.as_f64().unwrap()).collect();
    let points: Vec<[f64; 2]> = flat.chunks_exact(2).map(|p| [p[0], p[1]]).collect();
    for case in vectors["sampling"]["cases"].as_array().unwrap() {
        let mode = SamplingMode::parse(case["mode"].as_str());
        let radius = case["radius"].as_f64().unwrap();
        for (pixels, rgb) in [(&rgba, [0, 1, 2]), (&bgra, [2, 1, 0])] {
            let mut output = vec![0_u8; points.len() * 3];
            colour::sample_points(&Frame { pixels, width, height, rgb }, &points, radius, mode, &mut output);
            assert_eq!(hex(&output), str_of(case, "output"), "mode {mode:?} radius {radius}");
        }
    }
}

#[test]
fn calibration_matches_the_js_calibration() {
    let vectors = vectors();
    let c = &vectors["calibration"];
    let source = unhex(str_of(c, "source"));
    let previous = unhex(str_of(c, "previous"));
    for case in c["cases"].as_array().unwrap() {
        let mut output = vec![0_u8; source.len()];
        colour::calibrate(&source, &mut output, &options_of(&case["options"]), Some(&previous));
        assert_eq!(hex(&output), str_of(case, "output"), "{}", case["options"]);
    }
}

#[test]
fn test_patterns_match_the_js_patterns() {
    let vectors = vectors();
    let p = &vectors["patterns"];
    let previous = unhex(str_of(p, "previous"));
    for case in p["cases"].as_array().unwrap() {
        let mut output = vec![0_u8; previous.len()];
        let color = colour::parse_hex_color(case["color"].as_str());
        colour::fill_test_pattern(TestPattern::parse(case["pattern"].as_str()), color, case["nowMs"].as_f64().unwrap(), &mut output, &options_of(&case["options"]), Some(&previous));
        assert_eq!(hex(&output), str_of(case, "output"), "{case}");
    }
}

#[test]
fn a_plan_samples_and_packs_the_same_universes_as_the_editor_path() {
    let vectors = vectors();
    let (rgba, width, height) = picture(&vectors);
    let bgra = to_bgra(&rgba);
    let e2e = &vectors["endToEnd"];
    let plan = plan::parse_plan(&e2e["plan"]).unwrap();
    let frame = Frame { pixels: &bgra, width, height, rgb: [2, 1, 0] };
    let mut rgb_buffers = Vec::new();
    for fixture in &plan.fixtures {
        let length = fixture.pixel_count() * 3;
        let previous = vec![0_u8; length];
        let mut rgb = vec![0_u8; length];
        if fixture.test_pattern != TestPattern::Off {
            colour::fill_test_pattern(fixture.test_pattern, fixture.test_color, 0.0, &mut rgb, &fixture.options, Some(&previous));
        } else {
            let mut source = vec![0_u8; length];
            colour::sample_points(&frame, &fixture.points, fixture.sample_radius, fixture.sampling, &mut source);
            colour::calibrate(&source, &mut rgb, &fixture.options, Some(&previous));
        }
        assert_eq!(hex(&rgb), str_of(&e2e["pixels"], &fixture.id), "fixture {}", fixture.id);
        rgb_buffers.push(rgb);
    }
    let refs: Vec<&[u8]> = rgb_buffers.iter().map(Vec::as_slice).collect();
    let mut universes = Vec::new();
    plan::pack(&plan, &refs, &mut universes);
    let expected = e2e["universes"].as_array().unwrap();
    assert_eq!(universes.len(), expected.len());
    for (got, want) in universes.iter().zip(expected) {
        assert_eq!(got.protocol.name(), str_of(want, "protocol"));
        assert_eq!(got.host.map(|h| h.to_string()), want["host"].as_str().map(str::to_string));
        assert_eq!(got.universe as u64, want["universe"].as_u64().unwrap());
        assert_eq!(hex(&got.data), str_of(want, "data"), "universe {}", got.key);
    }
    // Packing twice into the reused buffers gives the same frame.
    let again: Vec<String> = universes.iter().map(|u| hex(&u.data)).collect();
    plan::pack(&plan, &refs, &mut universes);
    assert_eq!(universes.iter().map(|u| hex(&u.data)).collect::<Vec<_>>(), again);
}

#[test]
fn plans_reject_what_the_editor_would_not_send() {
    let base = serde_json::json!({ "fps": 40, "fixtures": [{ "id": "a", "points": [0.5, 0.5], "protocol": "artnet", "host": "10.0.0.1",
        "colorOrder": "RGB", "segments": [{ "universe": 0, "channel": 1, "firstPixel": 0, "pixelCount": 1 }] }] });
    assert!(plan::parse_plan(&base).is_ok());
    let mut no_host = base.clone();
    no_host["fixtures"][0]["host"] = Value::Null;
    assert!(plan::parse_plan(&no_host).is_err());
    let mut sacn_without_cid = base.clone();
    sacn_without_cid["fixtures"][0]["protocol"] = "sacn".into();
    sacn_without_cid["fixtures"][0]["segments"][0]["universe"] = 1.into();
    assert!(plan::parse_plan(&sacn_without_cid).is_err());
    let mut past_512 = base.clone();
    past_512["fixtures"][0]["segments"][0]["channel"] = 511.into();
    assert!(plan::parse_plan(&past_512).is_err());
    let mut fast = base.clone();
    fast["fps"] = 500.into();
    assert_eq!(plan::parse_plan(&fast).unwrap().fps, 60);
}

/// Every packet that arrives on `socket` until it goes quiet.
fn drain(socket: &UdpSocket) -> Vec<String> {
    socket.set_read_timeout(Some(Duration::from_millis(300))).unwrap();
    let mut out = Vec::new();
    let mut buffer = [0_u8; 1500];
    while let Ok((size, _)) = socket.recv_from(&mut buffer) {
        out.push(hex(&buffer[..size]));
    }
    out
}

#[test]
fn output_sends_the_same_packets_as_pixelmap_output_cjs() {
    let vectors = vectors();
    let scenario = &vectors["output"];
    let artnet = UdpSocket::bind("127.0.0.1:0").unwrap();
    let sacn = UdpSocket::bind("127.0.0.1:0").unwrap();
    let mut output = Output::new(artnet.local_addr().unwrap().port(), sacn.local_addr().unwrap().port());
    let settings = SacnSettings {
        priority: 110,
        source_name: packets::encode_source_name(Some("Scenario")),
        cid: packets::parse_sacn_cid(str_of(&vectors, "cid")).unwrap(),
    };
    let start = Instant::now();
    let results = scenario["results"].as_array().unwrap();
    for (frame, result) in scenario["frames"].as_array().unwrap().iter().zip(results) {
        let universes: Vec<UniverseFrame> = frame["universes"].as_array().unwrap().iter().map(|u| {
            let protocol = if u["protocol"] == "artnet" { Protocol::ArtNet } else { Protocol::Sacn };
            let host: Option<Ipv4Addr> = u["host"].as_str().map(|h| h.parse().unwrap());
            let universe = u["universe"].as_u64().unwrap() as u32;
            UniverseFrame {
                key: format!("{}|{}|{}", protocol.name(), host.map_or("multicast".to_string(), |h| h.to_string()), universe),
                protocol, host, universe, data: unhex(str_of(u, "data")),
            }
        }).collect();
        let at = start + Duration::from_millis(frame["at"].as_u64().unwrap());
        let sent = output.send_frame(&OutFrame { fps: 40, art_sync: true, sacn: &settings, universes: &universes }, at).unwrap();
        assert_eq!(!sent, result["dropped"].as_bool().unwrap(), "frame at {}", frame["at"]);
    }
    assert_eq!(output.stop() as u64, scenario["terminated"].as_u64().unwrap());
    let expected = scenario["sent"].as_array().unwrap();
    let want = |port: &str| expected.iter().filter(|p| p["port"] == port).map(|p| str_of(p, "packet").to_string()).collect::<Vec<_>>();
    assert_eq!(drain(&artnet), want("artnet"));
    assert_eq!(drain(&sacn), want("sacn"));
    assert_eq!(output.stats.packets_sent as usize, expected.len());
}

#[test]
fn a_handover_carries_sequences_without_a_black_frame() {
    let receiver = UdpSocket::bind("127.0.0.1:0").unwrap();
    let port = receiver.local_addr().unwrap().port();
    let settings = SacnSettings { priority: 100, source_name: packets::encode_source_name(None), cid: [1; 16] };
    let universe = |data: u8| vec![UniverseFrame { key: "artnet|127.0.0.1|0".into(), protocol: Protocol::ArtNet, host: Some(Ipv4Addr::LOCALHOST), universe: 0, data: vec![data; 6] }];
    let start = Instant::now();
    let mut first = Output::new(port, port);
    let frame = universe(9);
    first.send_frame(&OutFrame { fps: 40, art_sync: false, sacn: &settings, universes: &frame }, start).unwrap();
    first.send_frame(&OutFrame { fps: 40, art_sync: false, sacn: &settings, universes: &frame }, start + Duration::from_millis(25)).unwrap();
    let handover = super::output::Handover::from_json(&first.hand_over().to_json());
    let mut second = Output::new(port, port);
    second.take_over(&handover, &settings);
    let frame = universe(7);
    second.send_frame(&OutFrame { fps: 40, art_sync: false, sacn: &settings, universes: &frame }, start).unwrap();
    let packets = drain(&receiver);
    assert_eq!(packets.len(), 3, "no black frame on the hand-over");
    let sequences: Vec<u8> = packets.iter().map(|p| unhex(p)[12]).collect();
    assert_eq!(sequences, vec![1, 2, 3]);
    assert_eq!(unhex(&packets[2])[18], 7);
}
